# Remind an OPEN or PENDING claim on the sheet's today. A claim in any other status, or one already
# reminded on the sheet's today, is a 409 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
# Checks the rules and writes the reminded date only when none refuses it.
apply:
  class: net.officefloor.hq.app.claim.RemindClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the reminder is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Reminds an OPEN or PENDING claim on the sheet's today, once per day: any other status, or a
 * second reminder the same day, is refused and writes nothing.
 */
public class RemindClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository) throws InvalidClaimStatusException {
        claim.remind(sheet.today());
        if (!repository.remind(claim)) throw new InvalidClaimStatusException("The claim was already reminded today");
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the reminder, naming the claim like every claim line. */
public class AuditClaimReminded {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("REMIND", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim));
    }
}
-- The last sheet's today a reminder was written for an OPEN or PENDING claim; null when never reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- A claim's reminded date kept in its history too, so the sheet as of a date shows it. History kept
-- before this takes the reminded date the claim has now, where it is on or before that history's day.
ALTER TABLE claim_history ADD COLUMN reminded_on DATE;
UPDATE claim_history SET reminded_on = (SELECT c.reminded_on FROM claim c WHERE c.id = claim_history.claim_id
    AND c.reminded_on <= claim_history.set_on);
